xpath.script:
document.addEventListener('DOMContentLoaded', function () {
    function applyAssociationLabels() {
        const buttons = document.querySelectorAll('button[type="submit"], button.btn-primary');
        buttons.forEach(function (button) {
            const text = (button.textContent || '').trim();
            if (text === 'Payer maintenant') {
                button.textContent = 'Confirmer la commande';
            }
        });

        const elements = document.querySelectorAll('span, div, h2, p, strong, label');
        elements.forEach(function (element) {
            const text = (element.textContent || '').trim();
            if (text === 'Paiement') {
                element.textContent = 'Confirmation';
            }
        });
    }

    applyAssociationLabels();

    const observer = new MutationObserver(function () {
        applyAssociationLabels();
    });

    observer.observe(document.body, { childList: true, subtree: true });
});
